
#[cfg(test)]mod reverse_plan7_tests{
 use super::*;use crate::circuit::{Op,OperationType,analyze_ops};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
 struct Words{bytes:Vec<u8>,pos:usize}impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.copy_from_slice(&self.bytes[self.pos..self.pos+b.len()]);self.pos+=b.len();}}
 fn build(inverse:bool)->(Vec<Op>,Vec<QubitId>,Vec<QubitId>,QubitId,QubitId,crate::circuit::BitId,u32){
  let mut c=Builder::new();let a=c.alloc_qubits(56);let b=c.alloc_qubits(56);let cin=c.alloc_qubit();let sign=c.alloc_qubit();let guard=c.alloc_bit();let fake=c.alloc_qubits(2);let pad=c.alloc_qubits(1232-5-c.active_qubits()as usize);let all:Vec<_>=a.iter().chain(&b).copied().chain([cin,sign]).chain(pad.iter().copied()).collect();c.declare_qubit_register(&all);let rows:Vec<_>=a.iter().enumerate().map(|(i,&q)|{let mut f=l(q);if i%3==0{f=f.x(&l(sign));}if i%5==0{f=f.x(&Lin::k(true));}if i%7==0{f=f.x(&l(a[(i+7)%56]));}f}).collect();std::env::set_var("PEBBLE_HARD_CAP","1232");c.push_condition(guard);
  let(_,peak)=super::super::super::pingpong::with_phase_cap(Some(1232),||c.r3_peak(|c|{let(plan,lean,drops)=fold_plan_d(c,56,"reverse",2);assert!(lean);assert_eq!(plan,Y28_PLAN7.0);assert_eq!(drops,Y28_PLAN7.1);for q in fake{c.release_clean(q);}ladder_d(c,&b,&rows,6,cin,&plan,&drops);if inverse{for &q in &b{c.x(q);}ladder_d(c,&b,&rows,6,cin,&plan,&drops);for &q in &b{c.x(q);}}}));c.pop_condition();std::env::set_var("PEBBLE_HARD_CAP","1234");assert_eq!(peak,1232);(c.take_ops(),a,b,cin,sign,guard,peak)
 }
 fn run(inverse:bool,guard:u64,probe:Option<usize>){let(ops,a,b,cin,sign,bit,_)=build(inverse);let(nq,nb,_,_)=analyze_ops(ops.iter());assert_eq!(nq,1232);let nd=ops.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();let batches:Vec<_>=if probe.is_some(){vec![73]}else{(0..1024).collect()};
  for batch in batches{let mut h=Shake256::default();h.update(b"reverse-plan7-independent-inputs-v1");h.update(&(batch as u64).to_le_bytes());let mut reader=h.finalize_xof();let mut init=vec![0u64;nq as usize];for q in a.iter().chain(&b).copied().chain([cin,sign]){let mut bytes=[0u8;8];reader.read(&mut bytes);init[q.0 as usize]=u64::from_le_bytes(bytes);}let mut bytes=vec![0u8;nd*8];let mut h=Shake256::default();h.update(b"reverse-plan7-independent-measurements-v1");h.update(&(batch as u64).to_le_bytes());h.finalize_xof().read(&mut bytes);if let Some(p)=probe{if p==nd{for x in &mut bytes{*x=255;}}else{for x in &mut bytes[p*8..p*8+8]{*x^=255;}}}let mut rng=Words{bytes,pos:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);s.qubits.copy_from_slice(&init);s.bits[bit.0 as usize]=guard;s.apply_iter(ops.iter());assert_eq!(s.phase,0,"inverse{inverse} batch{batch} probe{probe:?}");
   for lane in 0..64{let mut source=0u64;let mut target=0u64;for i in 0..56{source|=((init[a[i].0 as usize]>>lane)&1)<<i;target|=((init[b[i].0 as usize]>>lane)&1)<<i;}let sg=init[sign.0 as usize]>>lane&1;let carry=init[cin.0 as usize]>>lane&1;let mut add=0u64;for i in 6..56{let v=(source>>i&1)^(u64::from(i%3==0)*sg)^u64::from(i%5==0)^(if i%7==0{source>>((i+7)%56)&1}else{0});add|=v<<(i-6);}let want=if inverse||guard>>lane&1==0{target}else{((((target>>6)+add+carry)&((1u64<<50)-1))<<6)|(target&63)};for i in 0..56{assert_eq!(s.qubits[b[i].0 as usize]>>lane&1,want>>i&1);}}
   for i in 0..nq as usize{if !b.iter().any(|q|q.0 as usize==i){assert_eq!(s.qubits[i],init[i]);}}drop(s);assert_eq!(rng.pos,nd*8);
  }
 }
 #[test]fn reverse_budget_seven_is_admitted_and_matches_full_affine_addition_inverse_guards_and_rng(){for inverse in[false,true]{for g in[0,0xA55A_DD33_FF00_1701,u64::MAX]{run(inverse,g,None);}let(ops,..)=build(inverse);let nd=ops.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();for p in 0..=nd{run(inverse,0xA55A_DD33_FF00_1701,Some(p));}}}
}
